// generated by appliance-ui v2.37.0 from tokens.json — do not edit; change appliance-ui and sync
// ApplianceNeeds: draws the "Needs you" list the same way in every app. Item data goes in through textContent only.
// renderList option dense: true makes one-line rows (no source line) for tight tiles.
// item: {id, source, tone: "bad"|"attention"|"warn", title, detail, link?, action?: {key, link}, urgent?, as_of?, area?, ack?}
// Acknowledge (2.28.0): an item with `ack: true` and an id, in a list given opts.onAck(id, item) → Promise, gets an
// Acknowledge button beside its link. The button is held from the first tap until the promise settles, so a second tap
// never calls onAck again; a rejection or a resolved `false` keeps the row and says "Not acknowledged. Try again.",
// anything else removes the row. A dense list draws no button (its rows are one line).
// Tone: bad is red; attention and warn are both amber (2.11.1; warn was muted before), so a warning never reads as information.
// The meta line (2.6.0, Pi Hub amendment A7 P2) is "since <as_of> · <area>": the area, else the source when it isn't
// this app (opts.self). renderList/render option when(date, now) → text overrides how as_of reads.
// Decisions (2.27.0, Pi Hub amendment A33 P1): renderDecisions(decisions, opts) draws the "Decisions (n)" group, one row per
// open question the owner answers by a tap. decision: {id, question, options[], recommended?, link?, kind: "choice"|"text",
// answered_at?, answer?}. opts.onAnswer(id, answer) → Promise does the write; a rejection or a resolved `false` is "not
// recorded" (the row stays), anything else is recorded (a resolved string is the answer the hub holds, shown as recorded).
// opts.state "loading" or "error" draws the group's own line instead of rows; "stale" keeps the rows given (the last ones
// read) under a Not current line, or says the decisions couldn't be read when there are none. An empty or missing list
// with no state draws nothing.
// opts.allowOrigins: absolute https origins a spec link may point at (others are dropped, as for items).
// 2.33 (Pi Hub A35 M1b): kind "multi" draws a box per option and one Send, and calls onAnswer with the ticked options
// (a list, in option order); kind "yesno" draws Yes and No. context, why_needed and rationale, when given, are drawn as
// text under the question. provenance(level, {when, source}) draws a fact's source label (A35 §7.1).
(() => {
  // The state words and the age rules, one table with the display (src/words.json). The build puts it on the next line
  // of dist/needs.js, so run dist/needs.js, not this file.
  const WORDS = {"state":{"up":"Up","down":"Down","unknown":"Unknown","running":"Running","waiting":"Waiting"},"control":{"back":"Back","home":"Home","on":"On","off":"Off","previous":"Previous","next":"Next","current_unknown":"Current setting unknown","not_saved":"Not saved","no_choices":"Nothing to choose"},"age":{"ago":[{"under":60,"text":"now"},{"under":3600,"per":60,"text":"{n} min ago"}],"since":"since {when}","until":"until {when}"}};
  const PHRASES = {
    judge: 'Judge the print', approve: 'Approve or drop', send: 'Send it to the printer', fix_plan: 'Fix the plan',
    look: 'Look at the printer', open_bambuddy: 'Open Bambuddy', check_pc: 'Check the PC', not_answering: "{name} isn't answering",
    // The platform's terms (spec section 9), the same on every surface.
    // 2.21 (Pi Hub A22 8.4): the PC that runs the Assistant sleeps, and that is normal. Asleep, then waking, then the page.
    pc_off: 'The PC is asleep', pc_waking: 'The PC is waking up',
    assistant_down: "The Assistant isn't answering", source_down: "{name} isn't answering",
    unknown_release: 'Not reported',
    // 2.27 (Pi Hub A33 P1): the Decisions group. {n} is a count, {answer} is what was recorded.
    decisions_heading: 'Decisions ({n})', decisions_loading: 'Loading decisions', decisions_unreadable: "Decisions couldn't be read",
    decision_recommended: 'Recommended', decision_spec: 'Open the spec', decision_text_label: 'Your answer', decision_send: 'Send',
    decision_pending: 'Recording your answer', decision_recorded: 'Recorded: {answer}', decision_failed: 'Not recorded. Try again.',
    decision_no_answer: "This decision can't be answered here", decision_empty: 'Write an answer first',
    decisions_stale: "Not current: couldn't refresh the decisions",
    // 2.33 (Pi Hub A35 M1b): the multi and yes/no rows, and what the asker wrote around the question. {text} is theirs.
    decision_yes: 'Yes', decision_no: 'No', decision_choose_label: 'Choose any that apply',
    decision_choose_one: 'Choose at least one first', decision_why_needed: 'Why it is asked: {text}',
    decision_rationale: 'Why it is recommended: {text}',
    // 2.33 (A35 §7.1): where a fact came from and how old it is. {when} and {source} are the app's own words.
    prov_live: 'Live', prov_reported: 'Reported {when}', prov_checked: 'Checked {when}', prov_imported: 'Imported from {source}',
    prov_owner: 'Recorded by you', prov_unavailable: 'No report since {when}', prov_never: 'No report yet',
    // A1 (2.8.0): a Healthchecks.io check is Late, Down or Paused while the hub is up.
    outside_alarm_quiet: "The outside alarm isn't hearing from the Pi",
    // Actions named by their verb (2.6.0, A7 P2; 2.34.1, A36 D4): never "Open" alone.
    judge_it: 'Judge it', open_printer: 'Open printer', open_network: 'Open Network', open_backups: 'Open Backups',
    see_usage: "See what's using it", see_running: "See what's running",
    // 2.28: the owner has seen an item that needs nothing more from them; the app hides it until it is raised again.
    acknowledge: 'Acknowledge', ack_pending: 'Acknowledging', ack_failed: 'Not acknowledged. Try again.',
  };
  const EMPTY = 'Nothing needs you right now.';
  const TONES = { bad: 1, attention: 1, warn: 1, info: 1 };
  const TEXT_MAX = 500;

  // Trust is decided from the input, after stripping tab/newline (browsers ignore them inside URLs) and trimming.
  // A #hash, a /path or an absolute http(s) URL (or //host) in the item is kept only if it is same-origin with `here`.
  // Anything else (e.g. "tool:bambuddy") goes to the resolver, whose result is kept only if it is an http(s) URL.
  function safeLink(link, opts) {
    const o = opts || {};
    if (typeof link !== 'string' || !o.here) return null;
    const input = link.replace(/[\t\n\r]/g, '').replace(/^[\x00-\x20]+|[\x00-\x20]+$/g, '');
    if (!input) return null;
    const parse = (v, base) => { try { return new URL(v, base); } catch (e) { return null; } };
    if (/^[#\/\\]/.test(input) || /^https?:/i.test(input)) {
      const u = parse(input, o.here);
      if (!u || (u.protocol !== 'https:' && u.protocol !== 'http:') || u.origin !== o.here.origin) return null;
      if (/^\/[\/\\]/.test(u.pathname) || (input[0] === '#' && u.hash.length < 2)) return null;
      u.username = ''; u.password = '';
      return { href: u.href, external: false };  // the full same-origin URL, never a path that could read as //host
    }
    if (!o.resolve) return null;
    let res;
    try { res = o.resolve(input); } catch (e) { return null; }
    if (typeof res !== 'string') return null;
    const u = parse(res.replace(/[\t\n\r]/g, '').replace(/^[\x00-\x20]+|[\x00-\x20]+$/g, ''));
    if (!u || (u.protocol !== 'https:' && u.protocol !== 'http:')) return null;
    u.username = ''; u.password = '';
    return { href: u.href, external: u.origin !== o.here.origin };
  }

  // The age rules: seconds since → "now" or "4 min ago"; null once the last rule is past (then use "since …").
  function ago(seconds) {
    if (typeof seconds !== 'number' || !Number.isFinite(seconds)) return null;
    const s = Math.max(0, seconds);
    const r = WORDS.age.ago.find(x => s < x.under);
    return r ? r.text.replace('{n}', Math.floor(s / (r.per || 1))) : null;
  }
  const sinceText = when => WORDS.age.since.replace('{when}', () => when);
  const untilText = when => (WORDS.age.until || 'until {when}').replace('{when}', () => when);

  // "since 4:29 AM" today, "since 3 Nov" before; nothing for a missing or unreadable time.
  function formatWhen(val, o) {
    if (val == null || val === '') return '';
    const d = new Date(val), now = o.now ? new Date(o.now) : new Date();
    if (Number.isNaN(d.getTime())) return '';
    if (typeof o.when === 'function') { const t = o.when(d, now); return typeof t === 'string' && t ? t : ''; }
    const today = d.toDateString() === now.toDateString();
    return today ? d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })
      : d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
  }
  function since(asOf, o) {
    const t = formatWhen(asOf, o);
    return t ? sinceText(t) : '';
  }
  function until(untilVal, o) {
    const t = formatWhen(untilVal, o);
    return t ? untilText(t) : '';
  }

  const hereOf = (o, doc) => o.here || new URL(doc.defaultView.location.href);
  function el(doc, tag, cls, text) {
    const e = doc.createElement(tag);
    if (cls) e.className = cls;
    if (text != null) e.textContent = text;
    return e;
  }
  const phrase = (key, item) => {
    const t = Object.hasOwn(PHRASES, key) ? PHRASES[key] : '';
    return t.includes('{name}') && !item.source ? '' : t.replace('{name}', () => item.source);
  };

  function render(item, opts) {
    const o = opts || {};
    const doc = o.doc || document;
    const here = hereOf(o, doc);
    const li = el(doc, 'li', 'ui-need');
    const headsUp = item.kind === 'heads_up';
    if (headsUp) li.dataset.kind = 'heads_up';
    li.dataset.tone = headsUp ? 'info' : (Object.hasOwn(TONES, item.tone) ? item.tone : 'warn');
    const act = item.action;
    const link = safeLink(item.link || (act && act.link), { resolve: o.resolve, here });
    const box = link ? el(doc, 'a', 'ui-need__link') : el(doc, 'div', 'ui-need__link');
    if (link) {
      box.setAttribute('href', link.href);
      if (link.external) { box.target = '_blank'; box.rel = 'noopener noreferrer'; }
    }
    box.append(el(doc, 'strong', 'ui-need__title', item.title), el(doc, 'span', 'ui-need__detail', item.detail));
    const meta = [since(item.as_of, o), until(item.until, o), item.area || (item.source !== o.self ? item.source : '')].filter(Boolean).join(' · ');
    if (meta) box.append(el(doc, 'span', 'ui-need__meta', meta));
    const words = !headsUp && act && phrase(act.key, item);  // empty for a heads-up row, an unknown key or a missing {name}
    if (words) box.append(el(doc, 'span', 'ui-need__action', words + (link && link.external ? ' ↗' : '')));
    else if (link && link.external) box.append(el(doc, 'span', 'ui-need__action', '↗'));
    li.append(box);
    const moreText = typeof item.more === 'string' ? item.more.trim() : '';
    if (moreText && !o.dense) {
      const details = el(doc, 'details', 'ui-need__details');
      details.append(el(doc, 'summary', 'ui-need__summary', 'Details'), el(doc, 'p', 'ui-need__more', moreText));
      li.append(details);
    }
    if (item.ack === true && !headsUp && !o.dense && typeof o.onAck === 'function' && typeof item.id === 'string' && item.id) ackControl(doc, li, item, o);
    return li;
  }

  // The Acknowledge button and its status line, outside the row's link (a button can't sit inside one).
  function ackControl(doc, li, item, o) {
    const b = el(doc, 'button', 'ui-btn ui-btn--ghost ui-need__ack', PHRASES.acknowledge);
    b.type = 'button';
    if (item.title) b.setAttribute('aria-label', `${PHRASES.acknowledge}: ${item.title}`);
    const note = el(doc, 'span', 'ui-need__note');
    note.setAttribute('role', 'status');
    const say = (words, kind) => { note.textContent = words; note.dataset.kind = kind; };
    let pending = false;
    b.addEventListener('click', async () => {
      if (pending) return;
      pending = true;
      b.setAttribute('aria-disabled', 'true');  // not `disabled`: the button keeps the focus while the write runs
      li.setAttribute('aria-busy', 'true');
      say(PHRASES.ack_pending, 'pending');
      let result;
      try { result = await Promise.resolve(o.onAck(item.id, item)); } catch (e) { result = false; }
      li.removeAttribute('aria-busy');
      if (result === false) {
        pending = false;
        b.removeAttribute('aria-disabled');
        say(PHRASES.ack_failed, 'failed');
        b.focus();
        return;
      }
      const ul = li.parentElement;
      const next = li.nextElementSibling || li.previousElementSibling;
      const focusNext = next && next.querySelector('a,button');
      li.remove();
      if (ul && !ul.children.length) {  // the last row: the list says so, and takes the focus the button had
        const empty = el(doc, 'p', 'ui-needs__empty', o.empty || EMPTY);
        empty.tabIndex = -1;
        ul.replaceWith(empty);
        empty.focus();
      } else if (focusNext) focusNext.focus();
    });
    li.classList.add('ui-need--ack');
    li.append(b, note);
  }

  function renderList(items, opts) {
    const o = opts || {};
    const doc = o.doc || document;
    const list = items || [];
    if (!list.length) return el(doc, 'p', 'ui-needs__empty', o.empty || EMPTY);
    const ul = el(doc, 'ul', o.dense ? 'ui-needs ui-needs--dense' : 'ui-needs');
    const shown = o.max > 0 ? list.slice(0, o.max) : list;
    for (const it of shown) ul.append(render(it, o));
    const more = o.more && shown.length < list.length ? safeLink(o.more.href, { resolve: l => l, here: hereOf(o, doc) }) : null;
    if (more) {
      const li = el(doc, 'li', 'ui-needs__more');
      const a = el(doc, 'a', null, o.more.label);
      a.setAttribute('href', more.href);
      li.append(a);
      ul.append(li);
    }
    return ul;
  }

  // ---- Decisions (2.27.0) ----
  let seq = 0;
  const text = (key, v) => (Object.hasOwn(PHRASES, key) ? PHRASES[key] : '')
    .replace('{n}', () => v).replace('{answer}', () => v).replace('{text}', () => v);

  // Provenance (2.33, Pi Hub A35 §7.1): one label saying where a fact came from, so every page says it one way.
  // level: live | reported | checked | imported | owner | unavailable (with no `when`: never reported). Only `live` draws
  // a lamp; every other level draws a hollow mark, so an import or a self-report never reads as a live reading. An
  // unknown level, or a level missing the words it needs, draws nothing rather than a label that claims too much.
  const PROV = { live: 'prov_live', reported: 'prov_reported', checked: 'prov_checked', imported: 'prov_imported',
    owner: 'prov_owner', unavailable: 'prov_unavailable' };
  function provenance(level, vals, opts) {
    const v = vals || {}, doc = (opts && opts.doc) || document;
    if (!Object.hasOwn(PROV, level)) return null;
    const key = level === 'unavailable' && !str(v.when) ? 'prov_never' : PROV[level];
    const words = PHRASES[key];
    if ((words.includes('{when}') && !str(v.when)) || (words.includes('{source}') && !str(v.source))) return null;
    const span = el(doc, 'span', 'ui-prov', words.replace('{when}', () => str(v.when)).replace('{source}', () => str(v.source)));
    span.dataset.level = level;
    return span;
  }
  const str = v => (typeof v === 'string' ? v.trim() : '');

  // Spec links: same-origin or resolver-produced as for items, else an absolute https URL on an origin the app allows.
  function decisionLink(link, o, here) {
    const safe = safeLink(link, { resolve: o.resolve, here });
    if (safe) return safe;
    if (typeof link !== 'string' || !Array.isArray(o.allowOrigins)) return null;
    let u;
    try { u = new URL(link.trim()); } catch (e) { return null; }
    if (u.protocol !== 'https:' || !o.allowOrigins.includes(u.origin)) return null;
    u.username = ''; u.password = '';
    return { href: u.href, external: true };
  }

  // One open decision as an li. `group` carries onAnswer, the live status line and the recorded() hook; the row is busy
  // from the first tap until the promise settles, so a second tap never calls onAnswer again.
  function renderDecision(d, o, here, group) {
    const doc = o.doc || document;
    const id = `ui-decision-${++seq}`;
    const isText = d.kind === 'text', isMulti = d.kind === 'multi', isYesNo = d.kind === 'yesno';
    // A yes/no question's two answers are the kit's own words, whatever the row carries.
    const options = isYesNo ? [text('decision_yes'), text('decision_no')]
      : [...new Set((Array.isArray(d.options) ? d.options : []).map(str).filter(Boolean))];
    const answerable = typeof o.onAnswer === 'function'
      && (isText || isYesNo || ((d.kind === 'choice' || isMulti) && options.length >= 2));
    const li = el(doc, 'li', 'ui-need ui-decision');
    li.dataset.tone = 'attention';
    li.dataset.state = 'open';
    li.dataset.decision = d.id;
    const body = el(doc, 'div', 'ui-decision__body');
    body.setAttribute('role', 'group');
    body.setAttribute('aria-labelledby', `${id}-q`);
    const q = el(doc, 'strong', 'ui-decision__q', d.question);
    q.id = `${id}-q`;
    const note = el(doc, 'p', 'ui-decision__note');
    note.id = `${id}-note`;
    note.setAttribute('role', 'status');
    const controls = [];
    const say = (words, kind) => { note.textContent = words; note.dataset.kind = kind || ''; };
    body.append(q);
    // What the asker wrote around the question (A35 §9.1), each as text under it.
    for (const [key, cls] of [['context', 'context'], ['why_needed', 'why'], ['rationale', 'why']]) {
      const v = str(d[key]);
      if (v) body.append(el(doc, 'p', `ui-decision__${cls}`, key === 'context' ? v : text(`decision_${key}`, v)));
    }

    const run = async (answer, trigger) => {
      if (li.dataset.state === 'pending' || !answer) return;
      li.dataset.state = 'pending';
      for (const c of controls) {
        c.setAttribute('aria-disabled', 'true');
        if (c.tagName === 'TEXTAREA') c.readOnly = true;
        if (c.tagName === 'INPUT') c.disabled = true;
      }
      li.setAttribute('aria-busy', 'true');
      say(text('decision_pending'), 'pending');
      let result;
      try { result = await Promise.resolve(o.onAnswer(d.id, answer)); } catch (e) { result = false; }
      li.removeAttribute('aria-busy');
      if (result === false) {
        li.dataset.state = 'failed';
        for (const c of controls) {
          c.removeAttribute('aria-disabled');
          if (c.tagName === 'TEXTAREA') c.readOnly = false;
          if (c.tagName === 'INPUT') c.disabled = false;
        }
        say(text('decision_failed'), 'failed');
        trigger.focus();
        return;
      }
      const shown = typeof result === 'string' && result ? result : answer;
      group.recorded(li, Array.isArray(shown) ? shown.join(', ') : shown);
    };

    if (isText) {
      const label = el(doc, 'label', 'ui-decision__label', text('decision_text_label'));
      label.setAttribute('for', `${id}-t`);
      const box = el(doc, 'textarea', 'ui-field ui-decision__text');
      box.id = `${id}-t`;
      box.rows = 3;
      box.maxLength = TEXT_MAX;
      box.setAttribute('aria-describedby', note.id);
      const send = el(doc, 'button', 'ui-btn ui-btn--primary ui-decision__send', text('decision_send'));
      send.type = 'button';
      send.addEventListener('click', () => {
        if (li.dataset.state === 'pending') return;
        const v = box.value.trim().slice(0, TEXT_MAX);
        if (!v) { say(text('decision_empty'), 'failed'); box.focus(); return; }
        run(v, send);
      });
      controls.push(box, send);
      body.append(label, box, send);
    } else if (isMulti) {
      // Several answers: a labelled box per option and one Send; the answer is the ticked options in their order.
      const set = el(doc, 'fieldset', 'ui-decision__options ui-decision__multi');
      set.append(el(doc, 'legend', 'ui-decision__label', text('decision_choose_label')));
      const boxes = options.map((opt, n) => {
        const label = el(doc, 'label', 'ui-decision__check');
        const box = el(doc, 'input', 'ui-check');
        box.type = 'checkbox';
        box.value = opt;
        box.id = `${id}-o${n}`;
        box.setAttribute('aria-describedby', note.id);
        label.append(box, el(doc, 'span', '', opt));
        if (opt === d.recommended || (Array.isArray(d.recommended) && d.recommended.includes(opt))) {
          label.append(el(doc, 'span', 'ui-decision__rec', text('decision_recommended')));
        }
        set.append(label);
        controls.push(box);
        return box;
      });
      const send = el(doc, 'button', 'ui-btn ui-btn--primary ui-decision__send', text('decision_send'));
      send.type = 'button';
      send.addEventListener('click', () => {
        if (li.dataset.state === 'pending') return;
        const picked = boxes.filter(b => b.checked).map(b => b.value);
        if (!picked.length) { say(text('decision_choose_one'), 'failed'); boxes[0]?.focus(); return; }
        run(picked, send);
      });
      controls.push(send);
      body.append(set, send);
    } else {
      const row = el(doc, 'div', 'ui-decision__options');
      for (const opt of options) {
        const rec = opt === d.recommended;
        const b = el(doc, 'button', 'ui-btn ui-btn--ghost', opt);
        b.type = 'button';
        if (rec) b.append(el(doc, 'span', 'ui-decision__rec', text('decision_recommended')));
        b.addEventListener('click', () => run(opt, b));
        controls.push(b);
        row.append(b);
      }
      body.append(row);
    }
    const link = str(d.link) ? decisionLink(d.link, o, here) : null;
    if (link) {
      const a = el(doc, 'a', 'ui-decision__link', text('decision_spec') + (link.external ? ' ↗' : ''));
      a.setAttribute('href', link.href);
      if (link.external) { a.target = '_blank'; a.rel = 'noopener noreferrer'; }
      body.append(a);
    }
    if (!answerable) { for (const c of controls) c.disabled = true; say(text('decision_no_answer'), 'failed'); }
    body.append(note);
    li.append(body);
    return li;
  }

  function renderDecisions(decisions, opts) {
    const o = opts || {};
    const doc = o.doc || document;
    const out = doc.createDocumentFragment();
    const open = (Array.isArray(decisions) ? decisions : [])
      .filter(d => d && typeof d === 'object' && str(d.id) && typeof d.question === 'string' && d.question.trim() && !d.answered_at);
    const state = ['loading', 'error', 'stale'].includes(o.state) ? (o.state === 'stale' && !open.length ? 'error' : o.state) : '';
    if (!open.length && !state) return out;
    const here = hereOf(o, doc);
    const sec = el(doc, 'section', 'ui-decisions');
    const titleId = `ui-decisions-${++seq}`;
    sec.setAttribute('aria-labelledby', titleId);
    const title = el(doc, 'h3', 'ui-decisions__title');
    title.id = titleId;
    const status = el(doc, 'p', 'ui-decisions__status');
    status.setAttribute('role', 'status');
    status.tabIndex = -1;
    const ul = el(doc, 'ul', 'ui-needs ui-decisions__list');
    const group = {
      recorded(li, answer) {
        const next = li.nextElementSibling || li.previousElementSibling;
        const focusNext = next && next.querySelector('input,button,textarea');
        li.remove();
        const left = ul.children.length;
        title.textContent = text('decisions_heading', left);
        if (!left) { title.hidden = true; ul.hidden = true; }
        status.textContent = text('decision_recorded', answer);
        status.dataset.kind = 'recorded';
        (focusNext || status).focus();
      },
    };
    if (state) {
      title.textContent = text('decisions_heading', open.length);
      title.hidden = !open.length;
      const age = state === 'stale' ? since(o.as_of, o) : '';
      const base = text({ loading: 'decisions_loading', error: 'decisions_unreadable', stale: 'decisions_stale' }[state]);
      status.textContent = age ? `${base} (${age})` : base;
      status.dataset.kind = state;
    } else {
      title.textContent = text('decisions_heading', open.length);
    }
    for (const d of open) ul.append(renderDecision(d, o, here, group));
    ul.hidden = !open.length;
    sec.append(title, status, ul);
    out.append(sec);
    return out;
  }

  const api = { render, renderList, renderDecisions, provenance, PHRASES, WORDS, ago, safeLink };
  if (typeof window !== 'undefined') window.ApplianceNeeds = api;
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
})();
